from collections import defaultdict, deque
from bisect import bisect

def buy_items_with_budget(n, p, items, q, budgets):
    happinesses = defaultdict(list)

    for c, h, t in items:
        happinesses[c].append((h, t))

    for h, t in happinesses.values():
        t.sort()

    result = []

    for aj, bj in budgets:
        max_h = 0

        for h, t in happinesses[aj]:
            left_index = bisect(bj, t - p)

            if left_index >= len(bj):
                max_h = max(max_h, h)
            else:
                time_left = bj[left_index] - t

                if time_left <= p:
                    max_h = max(max_h, h + h * (time_left - 1))

        result.append(max_h)

    return result

