def minimal_presses(n, k, phone_numbers):
    """
    Calculate the minimal total number of digit button presses Polycarp can achieve.

    Parameters:
    n (int): Number of phone numbers.
    k (int): Number of speed dial buttons.
    phone_numbers (List[Tuple[str, int]]): List of phone numbers and their frequency of dialing.

    Returns:
    int: The minimal total number of digit button presses.
    """
    results = {}
    memo = {}

    def select_single_number(ps, i, removed, freq, total):
        nonlocal results, memo
        if k <= len(ps):
            return freq * ps[len(ps) - 1] + freq * (k - len(ps))
        dp = 0

        for (s, f) in ps:
            count = 0
            for j, num in enumerate(removed):
                if s[j] != num:
                    count += 1
                if len(removed) - count <= len(ps):
                    break
            dp = max(dp, total + select_single_number(ps[:len(ps) - 1 - count], 0, removed[:] + (ps[j - len(ps) + count + 1:],), freq * (f - ps[len(ps) - 1 - count]), total + count * len(ps) - (f - ps[len(ps) - 1 - count]) + count))
        results[(i, removed)] = dp
        return dp

    ps = sorted(((len(s), s, (m - 1) if m > 0 else 0)) for s, m in phone_numbers)
    return select_single_number(ps, 0, tuple(), n, 0)

