import sys

def is_feasible(distance, distance_to_dest, number_to_change, count):
    if abs(number_to_change - distance) <= distance_to_dest:
        if distance_to_dest > 0:
            if number_to_change > distance:
                if count > distance_to_dest:
                    return True
                elif count > abs(number_to_change - distance):
                    return True
            else:
                if count < abs(number_to_change - distance):
                    return True
        else:
            if number_to_change < distance:
                if count > -distance_to_dest:
                    return True
                elif count < abs(number_to_change - distance):
                    return True
            else:
                if count < abs(number_to_change - distance):
                    return True
    return False

