from math import gcd

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inv(a, m):
    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        return -1  # Modular inverse does not exist
    return x % m

