import math

def count_divisors(n, mod):
    prime = []
    for i in range(2, int(math.sqrt(n)) + 1):
        while n % i == 0:
            if i not in prime:
                prime.append(i)
            n //= i
    if n > 1:
        if n not in prime:
            prime.append(n)
    for p in prime:
        exponent = 0
        while n > 0:
            n //= p
            exponent += n
        for j in range(len(prime)):
            if prime[j] != p:
                break
        else:
            return pow(((p // 2) + 1) * 2, exponent, mod)
    return (1 + pow(2, exponent, mod)) * pow(((p // 2) + 1) * 2, (exponent % 2), mod)

