import sys

def is_reachable(N, D, d, q, q_plan):
    queue = [(D, 0, 0)]  # (current distance, sequence so far, path at current distance)
    visited = {(D, '')}

    while queue:
        current_distance, seq, path = queue.pop(0)
        if current_distance == D:  
            return True

        for i in range(1, N+1):
            new_distance = current_distance + d[i-1]
            if new_distance >= D:
                continue
            elif new_distance not in visited:
                visited.add(new_distance)
                queue.append((new_distance, seq + str(i), path + ' ' + str(i)))
    return False

def process_queries(N, D, d, Q, plans):
    results = []
    for plan in plans:
        results.append(is_reachable(N, D, d, plan[2], plans[plan[0]][0]))
    return results

