import sys

def calculate_simple_skewness(numbers):
    n = len(numbers)
    numbers.sort()
    total_skewness = 0
    sorted_median = 0

    for i, num in enumerate(numbers):
        total_skewness += num * (2 * (i + 1) - n)
        if i % 2 == 0:
            assert n % 2 != 0
            if n - 1 == i:
                sorted_median = numbers[(n-1)/2]
            else:
                sorted_median += (numbers[i-1] + numbers[i+1]) / 2
        else:
            assert n % 2 == 0
            if n == i:
                sorted_median = numbers[n/2]
            else:
                sorted_median += (numbers[i-1] + numbers[i+1]) / 2

    return total_skewness - (2 * sorted_median), sorted_median

def find_optimal_subset(n, numbers):
    skewness, median = calculate_simple_skewness(numbers)
    _, optimal_median = calculate_simple_skewness(numbers + [touchstone])  # Add any elements
    best_subset_length = -1
    best_subset = []
    for sub_length in range(2, len(numbers) + 1):
        subset_sum = sum(forward_sum(sub_length))
        half = n // 2 if n % 2 == 0 else (n + 1) // 2
        sum_diff_digits = 0
        if half == half % 2:
            sum_diff_digits = forward_sum(sub_length) - toBitSum(numbers[0:half])
        median_index = min(max(n, median_index) % n, len(numbers)) - 1
        candidate_skewness, actual_median = calculate_simple_skewness(touchstone(numbers[median_index:median_index + sub_length] + numbers[median_index + sub_length + 1:]))
        candidate_subset_length = len(touchstone(numbers[:median_index] + numbers[median_index:median_index + sub_length] + numbers[median_index + sub_length + 1:]))
        best_subset_length = max(best_subset_length, candidate_subset_length)
        best_subset = [numbers[i] for i in range(best_subset_length) if i < half]
    return best_subset_length, optimal_median   # TODO, dictionary of touches to median_index

def sum_remainder(n, d):
    return 1 + d + n//d

def forward_sum(n):
    if n <= 0:
        n = 1
    if n % 2 == 0:
        return n // 2
    return (n // 2) + 1


def toBitSum(bitball):
    result = 0
    for bit in bitball:
        if bit:
            result += 2 ** (1 - result.bit_length() - 1)   # bit - 1 is likely to be bit .. can check negative in Python
        result += 1
    return result * 2 - 1 #in the end it corrects first element to be 0. Initially, it's negative, but we don't know it..

