def find_min_bricks(input_config):
    n, m = map(int, input_config[0].split())
    grid = [list(row) for row in input_config[1:]]

    def is_valid(row, col):
        if row < 0 or row >= n or col < 0 or col >= m:
            return False
        return grid[row][col] == '#'

    def count_covered(area):
        covered = sum(grid[row][col] == '#' for row in area for col in area[0])
        return area[1] - area[0][-1] + 1 - covered

    def neighbors(row, col):
        for dr, dc in [(-1, 0), (1, 0), (0, 1), (0, -1)]:
            yield row + dr, col + dc

    def find_bricks(area):
        visited = set()
        min_bricks = float('inf')
        for r0, c0 in area[0]:
            for r, c in ((r0, c0), (-r0, -c0)):
                if is_valid(r, c) and (r, c) not in visited:
                    current_bricks = 1 + sum(count_covered((r, c)) for r, c in neighbors(r, c))
                    min_bricks = min(min_bricks, current_bricks)
            visited.add((r0, c0))
        return min_bricks

    return find_bricks([(0, c) for c in range(m)]) + find_bricks([(r, 0) for r in range(n)])

