import sys
from collections import defaultdict

def parseInput():
    n = int(input())
    m = int(input())
    bricks = defaultdict(int)
    grid = []
    for _ in range(n):
        line = input()
        grid.append(line)
        for c in line:
            if c == "#":
                bricks[(0, 0)] += 1
            if c == ".":
                bricks[(1, 0)] += 1
                bricks[(0, 1)] += 1
    return n, m, bricks

def minimum_bricks(n, m, bricks):
    dp = [0] * (m + 1)
    for i in range(n):
        for j in range(m + 1):
            for (width, height) in bricks:
                if j - height <= m and width <= j and ((width, height) not in bricks):
                    bricks[(width, height)] += 1
                    dp[j] = max(dp[j], dp[j - height] + 1)
    return max(dp)

n, m, bricks = parseInput()
print(minimum_bricks(n, m, bricks))
